## 1. 1‑D Vector Addition

### CUDA version

```cpp
// vector_add.cu
#include <cuda_runtime.h>
#include <cstdio>

__global__ void vecAdd(const float *A, const float *B, float *C, int N)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) C[i] = A[i] + B[i];
}

int main()
{
    const int N = 1 << 20;          // 1M elements
    const int bytes = N * sizeof(float);

    float *h_A = (float*)malloc(bytes);
    float *h_B = (float*)malloc(bytes);
    float *h_C = (float*)malloc(bytes);

    for (int i = 0; i < N; ++i) {
        h_A[i] = i * 0.5f;
        h_B[i] = i * 1.5f;
    }

    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, bytes);
    cudaMalloc(&d_B, bytes);
    cudaMalloc(&d_C, bytes);

    cudaMemcpy(d_A, h_A, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, bytes, cudaMemcpyHostToDevice);

    const int blockSize = 256;
    const int gridSize  = (N + blockSize - 1) / blockSize;
    vecAdd<<<gridSize, blockSize>>>(d_A, d_B, d_C, N);
    cudaDeviceSynchronize();

    cudaMemcpy(h_C, d_C, bytes, cudaMemcpyDeviceToHost);

    // Verify
    for (int i = 0; i < N; ++i) {
        if (fabs(h_C[i] - (h_A[i] + h_B[i])) > 1e-5f) {
            printf("Mismatch at %d\n", i);
            break;
        }
    }

    cudaFree(d_A); cudaFree(d_B); cudaFree(d_C);
    free(h_A); free(h_B); free(h_C);
    return 0;
}
```

Compile & run:

```bash
nvcc -O3 vector_add.cu -o vector_add
./vector_add
```

### RAJA version

```cpp
// vector_add_raja.cpp
#include <RAJA/RAJA.hpp>
#include <cuda_runtime.h>
#include <cstdio>
#include <cmath>

int main()
{
    const int N = 1 << 20;          // 1M elements
    const int bytes = N * sizeof(float);

    float *h_A = (float*)malloc(bytes);
    float *h_B = (float*)malloc(bytes);
    float *h_C = (float*)malloc(bytes);

    for (int i = 0; i < N; ++i) {
        h_A[i] = i * 0.5f;
        h_B[i] = i * 1.5f;
    }

    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, bytes);
    cudaMalloc(&d_B, bytes);
    cudaMalloc(&d_C, bytes);

    cudaMemcpy(d_A, h_A, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, bytes, cudaMemcpyHostToDevice);

    // RAJA policy: 256 threads per block
    using ExecPolicy = RAJA::cuda_exec<256>;

    RAJA::forall<ExecPolicy>(RAJA::RangeSegment(0, N), [=] RAJA_DEVICE (int i) {
        d_C[i] = d_A[i] + d_B[i];
    });

    cudaDeviceSynchronize();

    cudaMemcpy(h_C, d_C, bytes, cudaMemcpyDeviceToHost);

    // Verify
    for (int i = 0; i < N; ++i) {
        if (fabs(h_C[i] - (h_A[i] + h_B[i])) > 1e-5f) {
            printf("Mismatch at %d\n", i);
            break;
        }
    }

    cudaFree(d_A); cudaFree(d_B); cudaFree(d_C);
    free(h_A); free(h_B); free(h_C);
    return 0;
}
```

Compile & run:

```bash
nvcc -O3 -std=c++17 vector_add_raja.cpp -lRAJA -o vector_add_raja
./vector_add_raja
```

> **Why it works**  
> `RAJA::forall` is a thin wrapper around a parallel loop.  
> The policy `RAJA::cuda_exec<256>` tells RAJA to launch a CUDA kernel with 256 threads per block.  
> The lambda is marked `RAJA_DEVICE` so it can be compiled for the device.  
> The rest of the code (memory allocation, copy, verification) is identical to the CUDA version.

