    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    // Allocate and initialize data
    float *a, *b, *c;
    cudaMalloc(&a, N * sizeof(float));
    cudaMalloc(&b, N * sizeof(float));
    cudaMalloc(&c, N * sizeof(float));

    // Initialize arrays
    for (int i = 0; i < N; ++i) {
        a[i] = i;
        b[i] = i * 2;
    }

    // RAJA version
    RAJA::ExecList exec_list;
    RAJA::forall<RAJA::cuda_exec<RAJA::seq_exec>>(RAJA::RangeSegment(0, N), exec_list,
        RAJA::LambdaExpr(i, a, b, c, N, threadsPerBlock, blocksPerGrid)(
            c[i] = a[i] + b[i]
        )
    );

    // Copy result back to host and print
    float *h_c = new float[N];
    cudaMemcpy(h_c, c, N * sizeof(float), cudaMemcpyDeviceToHost);
    for (int i = 0; i < N; ++i) {
        std::cout << "c[" << i << "] = " << h_c[i] << std::endl;
    }

    // Cleanup
    delete[] h_c;
    cudaFree(a);
    cudaFree(b);
    cudaFree(c);

    return 0;
}
```

### Example 2: Matrix Multiplication

#### CUDA Code
```cuda
__global__ void matMul(float *A, float *B, float *C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}
```

#### RAJA Code
```cpp
#include <RAJA/RAJA.hpp>
#include <iostream>

int main() {
    int N = 1024;
    int threadsPerBlock = 32;
    int blocksPerGridX = (N + threadsPerBlock - 1) / threadsPerBlock;
    int blocksPerGridY = (N + threadsPerBlock - 1) / threadsPerBlock;

    // Allocate and initialize data
    float *A, *B, *C;
    cudaMalloc(&A, N * N * sizeof(float));
    cudaMalloc(&B, N * N * sizeof(float));
    cudaMalloc(&C, N * N * sizeof(float));

    // Initialize arrays
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            A[i * N + j] = i;
            B[i * N + j] = j * 2;
        }
    }

    // RAJA version
    RAJA::ExecList exec_list;
    RAJA::forall<RAJA::cuda_exec<RAJA::seq_exec>>(RAJA::RangeSegment(0, N), RAJA::RangeSegment(0, N), exec_list,
        RAJA::LambdaExpr(row, col, A, B, C, N, threadsPerBlock, blocksPerGridX, blocksPerGridY)(
            float sum = 0.0f;
            for (int k = 0; k < N; ++k) {
                sum += A[row * N + k] * B[k * N + col];
            }
            C[row * N + col] = sum;
        )
    );

    // Copy result back to host and print
    float *h_C = new float[N * N];
    cudaMemcpy(h_C, C, N * N * sizeof(float), cudaMemcpyDeviceToHost);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cout << "C[" << i << "][" << j << "] = " << h_C[i * N + j] << std::endl;
        }
    }

    // Cleanup
    delete[] h_C;
    cudaFree(A);
    cudaFree(B);
    cudaFree(C);

    return 0;
}
```

### Explanation
1. **RAJA::forall**: This is the RAJA equivalent of a CUDA kernel. It takes a range of indices and a lambda function that performs the computation.
2. **RAJA::cuda_exec<RAJA::seq_exec>**: This specifies that the RAJA kernel should be executed on the GPU using CUDA. The `seq_exec` part indicates that the lambda function should be executed sequentially within each thread block.
3. **LambdaExpr**: This is used to define the lambda function that performs the computation.

These examples should give you a good starting point for converting your CUDA code to RAJA.
